head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDODS29010";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_attrReals();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods29010.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "td_31", attr: "__html", fn: function () { return ([String(dma_faqDetail.get("ldFaqAnsContn"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? (String(dma_faqDetail.get("ldFaqAnsContn")) + "<br/>") : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_list_onclick
 * @description 「목록으로」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_list_onclick = function(e){
    try {
        scwin.list()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods29010.btn_list_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name list
 * @description list 처리
 * @returns {void}
 * @hidden N
 */
scwin.list = function () {
    $('#ipt_SCREN_ID', $('#searchForm')).val("/ui/jsp/JLDODS29000.xml");
    $('#ipt_method', $('#searchForm')).val("readFaqList");
    $('#searchForm').submit();
};

/**
 * @method
 * @name fileDownRelLaw
 * @description file Down Rel Law 처리
 * @param {*} roomNo roomNo
 * @param {*} ipt_attachSeq ipt_attachSeq
 * @param {String} fileNm fileNm
 * @returns {void}
 * @hidden N
 */
scwin.fileDownRelLaw = function (roomNo, ipt_attachSeq, fileNm) {
    $('#ipt_sprtRoomNo', $('#attachForm')).val(roomNo);
    $('#ipt_attachSeq', $('#attachForm')).val(ipt_attachSeq);
    $('#ipt_attachFileNm', $('#attachForm')).val(fileNm);
    $('#ipt_SCREN_ID', $('#attachForm')).val("JLDODS20030");
    $('#ipt_method', $('#attachForm')).val("searchBbsAttachFile2");
    $('#attachForm').submit();
};

/**
 * @method
 * @name openPopRelLaw
 * @description open Pop Rel Law 처리
 * @param {*} sprtRoomContn sprtRoomContn
 * @returns {void}
 * @hidden N
 */
scwin.openPopRelLaw = function (sprtRoomContn) {
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(sprtRoomContn), { id: "_blank", resizable: true, type: "pageFramePopup" }, {});
};
